import java.util.*;

public class Main {
    static int[] parent, size;

    static void init(int n) {
        parent = new int[n + 1];
        size = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    static int find(int x) {
        if (parent[x] == x) return x;
        parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) { int t = a; a = b; b = t; }
        parent[b] = a;
        size[a] += size[b];
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        int n = 4;
        int[][] edges = {{1, 2}, {1, 3}, {3, 4}};
        List<List<Integer>> g = new ArrayList<>();
        for (int i=0;i<n+1;i++) g.add(new ArrayList<>());
        for (int[] e : edges) g.get(e[0]).add(e[1]);
        int[] indegree = new int[n+1];
        for (int[] e : edges) indegree[e[1]]++;
        Queue<Integer> q = new ArrayDeque<>();
        for (int i=1;i<=n;i++) if (indegree[i]==0) q.add(i);
        List<Integer> order = new ArrayList<>();
        while (!q.isEmpty()) {
            int u=q.poll(); order.add(u);
            for (int v:g.get(u)) if (--indegree[v]==0) q.add(v);
        }
        System.out.println(order);
    }
}

